<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Http\Requests\Admin\StoreMediaRequest; use App\Models\AuditLog; use App\Models\Media; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class MediaUploadController extends Controller { public function store(StoreMediaRequest $request) { $file=$request->file('image'); $dimensions=getimagesize($file->getRealPath()); $directory='media/'.now()->format('Y/m'); $base=Str::slug((string) $request->input('article_title')); if ($base === '') $base=Str::slug(pathinfo($file->getClientOriginalName(), PATHINFO_FILENAME)) ?: 'gambar'; $extension=strtolower($file->extension()); $filename=$base.'.'.$extension; $counter=1; while (Storage::disk('public')->exists($directory.'/'.$filename)) { $filename=$base.'-'.$counter.'.'.$extension; $counter++; } $path=$file->storeAs($directory,$filename,'public'); $media=Media::create(['disk'=>'public','path'=>$path,'original_name'=>$filename,'mime_type'=>$file->getMimeType(),'size'=>$file->getSize(),'width'=>$dimensions[0],'height'=>$dimensions[1],'uploaded_by'=>$request->user()->id,'is_temporary'=>true]); AuditLog::record('media.uploaded', $media); return response()->json(['id'=>$media->id,'url'=>$media->url(),'name'=>$media->original_name]); } }
